Analyze the following C++ code snippet and identify all potential issues including memory leaks, race conditions, and undefined behavior. Provide a corrected version with explanations for each fix:

```cpp
#include <vector>
#include <thread>
#include <iostream>

class DataProcessor {
    std::vector<int>* data;
    int* result;
public:
    DataProcessor() : data(new std::vector<int>()), result(nullptr) {}
    ~DataProcessor() { delete result; }
    void addData(int v) { data->push_back(v); }
    int* process() {
        auto& d = *data;
        result = new int(0);
        for (size_t i = 0; i < d.size(); i++) {
            *result += d[i];
        }
        return result;
    }
};
```
